-- Every federal prime contract award for FY2025 -- who got paid, how much, for what.
-- Auto-generated by scripts/gen_evidence_pages.py: 6,325,622 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("ACTION_DATE") as year, count(*) as records
from THE_LIBRARY.GOVERNMENT_SPENDING.FEDERAL_CONTRACTS
where "ACTION_DATE" is not null
group by 1
order by 1
